44: import static io.netty.handler.codec.http.HttpResponseStatus.NOT_FOUND;
45: 
46: @ChannelHandler.Sharable
47: public class NettyHandlerAdapter extends ChannelInboundMessageHandlerAdapter<FullHttpRequest> {
48: 
49:   private final Handler handler;
50:   private final RootContext rootContext;
51:   private Handler return404;
52: 
53:   public NettyHandlerAdapter(Handler handler, File baseDir) {
54:     this.handler = new ErrorCatchingHandler(handler);
55:     this.rootContext = new RootContext(
56:       ImmutableList.of(
57:         new DefaultServerErrorHandler(),
58:         new DefaultClientErrorHandler(),
59:         new ActivationBackedMimeTypes(),
60:         new DefaultFileSystemBinding(baseDir)
61:       )
62:     );
63: 
64:     return404 = new ClientErrorHandler(NOT_FOUND.code());
65:   }
66: 
67:   public void messageReceived(ChannelHandlerContext ctx, FullHttpRequest nettyRequest) throws Exception {
68:     if (!nettyRequest.getDecoderResult().isSuccess()) {
69:       sendError(ctx, HttpResponseStatus.BAD_REQUEST);
70:       return;
71:     }
72: 
73:     FullHttpResponse nettyResponse = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK);
74: 
75:     Request request = new DefaultRequest(nettyRequest);
76: 
77:     HttpVersion version = nettyRequest.getProtocolVersion();
78:     boolean keepAlive = version == HttpVersion.HTTP_1_1
79:         || (version == HttpVersion.HTTP_1_0 && "Keep-Alive".equalsIgnoreCase(nettyRequest.headers().get("Connection")));
80: 
81:     Response response = new DefaultResponse(nettyResponse, ctx.channel(), keepAlive, version);
82:     final Exchange exchange = new DefaultExchange(request, response, ctx, rootContext, return404);
83: 
84:     handler.handle(exchange);
85:   }
86: 
87:   public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
88:     cause.printStackTrace();
89:     if (ctx.channel().isActive()) {
90:       sendError(ctx, HttpResponseStatus.INTERNAL_SERVER_ERROR);
91:     }
92:   }
93: 
94:   private static void sendError(ChannelHandlerContext ctx, HttpResponseStatus status) {
95:     FullHttpResponse response = new DefaultFullHttpResponse(
96:         HttpVersion.HTTP_1_1, status, Unpooled.copiedBuffer("Failure: " + status.toString() + "\r\n", CharsetUtil.UTF_8));
97:     response.headers().set(HttpHeaders.Names.CONTENT_TYPE, "text/plain; charset=UTF-8");
98: 
99:     // Close the connection as soon as the error message is sent.
100:     ctx.write(response).addListener(ChannelFutureListener.CLOSE);
101:   }
102: }
