17: package ratpack.file.internal;
18: 
19: import io.netty.channel.*;
20: import io.netty.handler.codec.http.*;
21: import ratpack.block.Blocking;
22: import ratpack.util.Action;
23: 
24: import java.io.Closeable;
25: import java.io.File;
26: import java.io.FileInputStream;
27: import java.io.IOException;
28: import java.nio.channels.FileChannel;
29: import java.nio.file.attribute.BasicFileAttributes;
30: import java.util.concurrent.Callable;
31: 
32: import static io.netty.handler.codec.http.HttpHeaders.Names.CONNECTION;
33: import static io.netty.handler.codec.http.HttpHeaders.isKeepAlive;
34: 
35: public class DefaultFileHttpTransmitter implements FileHttpTransmitter {
36: 
37:   private final HttpRequest request;
38:   private final HttpResponse response;
39:   private final Channel channel;
40: 
41:   public DefaultFileHttpTransmitter(HttpRequest request, HttpResponse response, Channel channel) {
42:     this.request = request;
43:     this.response = response;
44:     this.channel = channel;
45:   }
46: 
47:   @Override
48:   public void transmit(Blocking blocking, final BasicFileAttributes basicFileAttributes, final File file) {
49:     blocking.exec(new Callable<FileChannel>() {
50:       public FileChannel call() throws Exception {
51:         return new FileInputStream(file).getChannel();
52:       }
53:     }).then(new Action<FileChannel>() {
54:       public void execute(FileChannel fileChannel) {
55:         transmit(basicFileAttributes, fileChannel);
56:       }
57:     });
58:   }
59: 
60:   private void transmit(BasicFileAttributes basicFileAttributes, final FileChannel fileChannel) {
61:     long length = basicFileAttributes.size();
62: 
63:     response.headers().set(HttpHeaders.Names.CONTENT_LENGTH, length);
64: 
65:     if (isKeepAlive(request)) {
66:       response.headers().set(CONNECTION, HttpHeaders.Values.KEEP_ALIVE);
67:     }
68: 
69:     if (!channel.isOpen()) {
70:       closeQuietly(fileChannel);
71:       return;
72:     }
73: 
74:     HttpResponse minimalResponse = new DefaultHttpResponse(response.getProtocolVersion(), response.getStatus());
75:     minimalResponse.headers().set(response.headers());
76:     ChannelFuture writeFuture = channel.writeAndFlush(minimalResponse);
77: 
78:     writeFuture.addListener(new ChannelFutureListener() {
79:       public void operationComplete(ChannelFuture future) throws Exception {
80:         if (!future.isSuccess()) {
81:           closeQuietly(fileChannel);
82:           channel.close();
83:         }
84:       }
85:     });
86: 
87:     FileRegion message = new DefaultFileRegion(fileChannel, 0, length);
88:     writeFuture = channel.write(message);
89: 
90:     writeFuture.addListener(new ChannelFutureListener() {
91:       public void operationComplete(ChannelFuture future) {
92:         closeQuietly(fileChannel);
93:         if (!future.isSuccess()) {
94:           channel.close();
95:         }
96:       }
97:     });
98: 
99:     ChannelFuture lastContentFuture = channel.writeAndFlush(LastHttpContent.EMPTY_LAST_CONTENT);
100:     if (!isKeepAlive(response)) {
101:       lastContentFuture.addListener(ChannelFutureListener.CLOSE);
102:     }
103:   }
104: 
105:   private void closeQuietly(Closeable closeable) {
106:     try {
107:       closeable.close();
108:     } catch (IOException e1) {
109:       throw new RuntimeException(e1);
110:     }
111:   }
112: 
113: }
