441:   @ChannelHandler.Sharable
442:   class ReloadHandler extends ChannelInboundHandlerAdapter {
443:     private ServerConfig lastServerConfig;
444:     private DefinitionBuild definitionBuild;
445:     private final Throttle reloadThrottle = Throttle.ofSize(1);
446: 
447:     private ChannelHandler inner;
448: 
449:     public ReloadHandler(DefinitionBuild definition) {
450:       super();
451:       this.definitionBuild = definition;
452:       this.lastServerConfig = definitionBuild.getServerConfig();
453:       try {
454:         this.inner = buildAdapter(definitionBuild);
455:       } catch (Exception e) {
456:         this.inner = null;
457:         serverRegistry = buildServerRegistry(lastServerConfig, r -> r);
458:       }
459:     }
460: 
461:     @Override
462:     public void channelActive(ChannelHandlerContext ctx) throws Exception {
463:       ctx.read();
464:       super.channelActive(ctx);
465:     }
466: 
467:     ChannelHandler getDelegate() {
468:       return inner;
469:     }
470: 
471:     @Override
472:     public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
473:       execController.fork().eventLoop(ctx.channel().eventLoop()).start(e ->
474:           Promise.<ChannelHandler>of(f -> {
475:             boolean rebuild = false;
476: 
477:             if (inner == null || definitionBuild.error != null) {
478:               rebuild = true;
479:             } else if (msg instanceof HttpRequest) {
480:               Optional<ReloadInformant> reloadInformant = serverRegistry.first(RELOAD_INFORMANT_TYPE, r -> r.shouldReload(serverRegistry) ? r : null);
481:               if (reloadInformant.isPresent()) {
482:                 LOGGER.debug("reload requested by '" + reloadInformant.get() + "'");
483:                 rebuild = true;
484:               }
485:             }
486: 
487:             if (rebuild) {
488:               Blocking.get(() -> {
489:                 definitionBuild = buildUserDefinition();
490:                 lastServerConfig = definitionBuild.getServerConfig();
491:                 return buildAdapter(definitionBuild);
492:               })
493:                 .wiretap(r -> {
494:                   if (r.isSuccess()) {
495:                     inner = r.getValue();
496:                   }
497:                 })
498:                 .mapError(this::buildErrorRenderingAdapter)
499:                 .result(f::accept);
500:             } else {
501:               f.success(inner);
502:             }
503:           })
504:             .wiretap(r -> {
505:               try {
506:                 ctx.pipeline().remove("inner");
507:               } catch (Exception ignore) {
508:                 // ignore
509:               }
510:               ctx.pipeline().addLast("inner", r.getValueOrThrow());
511:             })
512:             .throttled(reloadThrottle)
513:             .then(adapter -> ctx.fireChannelRead(msg))
514:       );
515:     }
516: 
517:     private NettyHandlerAdapter buildErrorRenderingAdapter(Throwable e) {
518:       try {
519:         return new NettyHandlerAdapter(serverRegistry, context -> context.error(e));
520:       } catch (Exception e1) {
521:         throw uncheck(e);
522:       }
523:     }
524: 
525:   }
