205:   protected Channel buildChannel(final ServerConfig serverConfig, final ChannelHandler handlerAdapter) throws InterruptedException {
206: 
207:     SSLContext sslContext = serverConfig.getSslContext();
208:     boolean requireClientSslAuth = serverConfig.isRequireClientSslAuth();
209:     this.useSsl = sslContext != null;
210: 
211:     ServerBootstrap serverBootstrap = new ServerBootstrap();
212: 
213:     serverConfig.getConnectTimeoutMillis().ifPresent(i -> {
214:       serverBootstrap.option(ChannelOption.CONNECT_TIMEOUT_MILLIS, i);
215:       serverBootstrap.childOption(ChannelOption.CONNECT_TIMEOUT_MILLIS, i);
216:     });
217:     serverConfig.getMaxMessagesPerRead().ifPresent(i -> {
218:       FixedRecvByteBufAllocator allocator = new FixedRecvByteBufAllocator(i);
219:       serverBootstrap.option(ChannelOption.RCVBUF_ALLOCATOR, allocator);
220:       serverBootstrap.childOption(ChannelOption.RCVBUF_ALLOCATOR, allocator);
221:     });
222:     serverConfig.getReceiveBufferSize().ifPresent(i -> {
223:       serverBootstrap.option(ChannelOption.SO_RCVBUF, i);
224:       serverBootstrap.childOption(ChannelOption.SO_RCVBUF, i);
225:     });
226:     serverConfig.getWriteSpinCount().ifPresent(i -> {
227:       serverBootstrap.option(ChannelOption.WRITE_SPIN_COUNT, i);
228:       serverBootstrap.childOption(ChannelOption.WRITE_SPIN_COUNT, i);
229:     });
230: 
231:     return serverBootstrap
232:       .group(execController.getEventLoopGroup())
233:       .channel(ChannelImplDetector.getServerSocketChannelImpl())
234:       .option(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
235:       .childOption(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
236:       .childHandler(new ChannelInitializer<SocketChannel>() {
237:         @Override
238:         protected void initChannel(SocketChannel ch) throws Exception {
239:           ChannelPipeline pipeline = ch.pipeline();
240:           if (sslContext != null) {
241:             SSLEngine sslEngine = sslContext.createSSLEngine();
242:             sslEngine.setUseClientMode(false);
243:             sslEngine.setNeedClientAuth(requireClientSslAuth);
244:             pipeline.addLast("ssl", new SslHandler(sslEngine));
245:           }
246: 
247:           pipeline.addLast("decoder", new HttpRequestDecoder(4096, 8192, 8192, false));
248:           pipeline.addLast("encoder", new HttpResponseEncoder());
249:           pipeline.addLast("deflater", new IgnorableHttpContentCompressor());
250:           pipeline.addLast("chunkedWriter", new ChunkedWriteHandler());
251:           pipeline.addLast("adapter", handlerAdapter);
252:           ch.config().setAutoRead(false);
253:         }
254:       })
255:       .bind(buildSocketAddress(serverConfig))
256:       .sync()
257:       .channel();
258:   }
