215:       serverBootstrap.childOption(ChannelOption.CONNECT_TIMEOUT_MILLIS, i);
216:     });
217:     serverConfig.getMaxMessagesPerRead().ifPresent(i -> {
218:       FixedRecvByteBufAllocator allocator = new FixedRecvByteBufAllocator(i);
219:       serverBootstrap.option(ChannelOption.RCVBUF_ALLOCATOR, allocator);
220:       serverBootstrap.childOption(ChannelOption.RCVBUF_ALLOCATOR, allocator);
221:     });
222:     serverConfig.getReceiveBufferSize().ifPresent(i -> {
223:       serverBootstrap.option(ChannelOption.SO_RCVBUF, i);
224:       serverBootstrap.childOption(ChannelOption.SO_RCVBUF, i);
225:     });
226:     serverConfig.getWriteSpinCount().ifPresent(i -> {
227:       serverBootstrap.option(ChannelOption.WRITE_SPIN_COUNT, i);
228:       serverBootstrap.childOption(ChannelOption.WRITE_SPIN_COUNT, i);
229:     });
