231:     return serverBootstrap
232:       .group(execController.getEventLoopGroup())
233:       .channel(ChannelImplDetector.getServerSocketChannelImpl())
234:       .option(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
235:       .childOption(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
236:       .childHandler(new ChannelInitializer<SocketChannel>() {
237:         @Override
238:         protected void initChannel(SocketChannel ch) throws Exception {
239:           ChannelPipeline pipeline = ch.pipeline();
240:           if (sslContext != null) {
241:             SSLEngine sslEngine = sslContext.createSSLEngine();
242:             sslEngine.setUseClientMode(false);
243:             sslEngine.setNeedClientAuth(requireClientSslAuth);
244:             pipeline.addLast("ssl", new SslHandler(sslEngine));
