247:           pipeline.addLast("decoder", new HttpRequestDecoder(4096, 8192, 8192, false));
248:           pipeline.addLast("encoder", new HttpResponseEncoder());
249:           pipeline.addLast("deflater", new IgnorableHttpContentCompressor());
