400:   private <E> void executeEvents(Iterator<? extends Service> services, E event, BiAction<Service, E> action, BiAction<? super Service, ? super Throwable> onError) throws Exception {
401:     if (!services.hasNext()) {
402:       return;
403:     }
404: 
405:     CountDownLatch latch = new CountDownLatch(1);
406:     AtomicReference<Throwable> error = new AtomicReference<>();
407:     executeEvents(services, latch, error, event, action, onError);
408:     latch.await();
409: 
410:     Throwable thrown = error.get();
411:     if (thrown != null) {
412:       throw Exceptions.toException(thrown);
413:     }
414:   }
