40:     @Override
41:     protected List<Runnable> initialValue() {
42:       return new LinkedList<>();
43:     }
44:   };
45: 
46:   private final ListeningScheduledExecutorService computeExecutor;
47:   private final ListeningExecutorService blockingExecutor;
48:   private final EventLoopGroup eventLoopGroup;
49:   private final ExecControl control;
50: 
51:   public DefaultExecController(int numThreads) {
52:     this.eventLoopGroup = new NioEventLoopGroup(numThreads, new ExecControllerBindingThreadFactory("ratpack-compute", Thread.MAX_PRIORITY));
53:     this.computeExecutor = MoreExecutors.listeningDecorator(eventLoopGroup);
54:     this.blockingExecutor = MoreExecutors.listeningDecorator(Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory("ratpack-blocking", Thread.NORM_PRIORITY)));
