58:   public static Optional<ExecController> getThreadBoundController() {
59:     return Optional.fromNullable(THREAD_BINDING.get());
60:   }
61: 
62:   public static ExecContext getThreadBoundContext() {
63:     return getThreadBoundController().get().getContext();
64:   }
65: 
66:   public void shutdown() throws Exception {
67:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
68:     blockingExecutor.shutdown();
69:   }
