71:   @Override
72:   public ExecContext getExecution() throws NoBoundContextException {
73:     ExecContext.Supplier contextSupplier = contextSupplierThreadLocal.get();
74:     if (contextSupplier == null) {
75:       throw new NoBoundContextException("No context is bound to the current thread (are you calling this from a blocking operation?)");
76:     } else {
77:       return contextSupplier.get();
78:     }
79:   }
