95:   private void exec(final ExecContext.Supplier execContextSupplier, final ExecInterceptor.ExecType execType, final Action<? super ExecContext> action) {
96:     if (isManagedThread()) {
97:       doExec(execContextSupplier, execType, action);
98:     } else {
99:       eventLoopGroup.execute(new Runnable() {
100:         @Override
101:         public void run() {
102:           doExec(execContextSupplier, execType, action);
103:         }
104:       });
105:     }
106:   }
107: 
108:   private void doExec(ExecContext.Supplier execContextSupplier, final ExecInterceptor.ExecType execType, final Action<? super ExecContext> action) {
109:     try {
110:       contextSupplierThreadLocal.set(execContextSupplier);
111:       new InterceptedOperation(execType, getExecution().getInterceptors()) {
112:         @Override
113:         protected void performOperation() throws Exception {
114:           action.execute(getExecution());
115:         }
116:       }.run();
117:     } catch (Throwable e) {
118:       onExecFinish.get().clear();
119:       ExecException.wrapAndForward(getExecution(), e);
120:       contextSupplierThreadLocal.remove();
121:     }
122: 
123:     try {
124:       List<Runnable> runnables = onExecFinish.get();
125:       while (!runnables.isEmpty()) {
126:         runnables.remove(0).run();
127:       }
128:     } finally {
129:       contextSupplierThreadLocal.remove();
130:     }
131:   }
