145:           private Exception exception;
146:           private T result;
147: 
148:           @Override
149:           public T call() throws Exception {
150:             exec(context.getSupplier(), ExecInterceptor.ExecType.BLOCKING, new Action<ExecContext>() {
151:               @Override
152:               public void execute(ExecContext thing) throws Exception {
153:                 try {
154:                   result = operation.call();
155:                 } catch (Exception e) {
156:                   exception = e;
157:                 }
158:               }
159:             });
160: 
161:             if (exception != null) {
162:               throw exception;
163:             } else {
164:               return result;
165:             }
166:           }
167:         }
