53: 
54:   private final Handler rest;
55: 
56:   public RequestTimingHandler(Handler rest) {
57:     this.rest = rest;
58:   }
59: 
60:   @Override
61:   public void handle(final Context context) throws Exception {
62:     final MetricRegistry metricRegistry = context.get(MetricRegistry.class);
63:     final Request request = context.getRequest();
64:     BackgroundExecTimingInterceptor blockingExecTimingInterceptor = new BackgroundExecTimingInterceptor(metricRegistry, request);
65: 
66:     context.addExecInterceptor(blockingExecTimingInterceptor, new Action<Context>() {
67:       @Override
68:       public void execute(Context context) throws Exception {
69:         String tag = buildRequestTimerTag(request.getUri(), request.getMethod().getName());
70:         final Timer.Context timer = metricRegistry.timer(tag).time();
71:         context.onClose(new Action<RequestOutcome>() {
72:           public void execute(RequestOutcome thing) throws Exception {
73:             timer.stop();
74:           }
75:         });
76:         context.insert(rest);
77:       }
78:     });
79:   }
